package solution

import "testing"

func TestEncodeLayoutExactAndNonMutation(t *testing.T) {
	l := Layout{Material:"steel", Capacity:10, Gap:2, Segments:[]Segment{{"A",3},{"B",4}}, Marks:[]int{0,10,4}}
	want := "LAYOUT/1\n[base]\nmaterial=steel\ncapacity=10\n[segments]\nA:3\nB:4\n[marks]\n0\n10\n4\n[totals]\nused=9\nremaining=1\n"
	got, err := EncodeLayout(l)
	if err != nil || got != want { t.Fatalf("got %q, %v; want %q", got, err, want) }
	if l.Segments[0] != (Segment{"A",3}) || l.Marks[1] != 10 { t.Fatal("input mutated") }
}

func TestEncodeLayoutEmptyLists(t *testing.T) {
	got, err := EncodeLayout(Layout{Material:"m", Capacity:0})
	want := "LAYOUT/1\n[base]\nmaterial=m\ncapacity=0\n[segments]\n[marks]\n[totals]\nused=0\nremaining=0\n"
	if err != nil || got != want { t.Fatalf("got %q, %v", got, err) }
}

func TestEncodeLayoutRejectsMalformed(t *testing.T) {
	cases := []Layout{
		{Capacity:1},
		{Material:"m", Capacity:-1},
		{Material:"m", Capacity:1, Gap:-1},
		{Material:"m", Capacity:1, Segments:[]Segment{{"",1}}},
		{Material:"m", Capacity:1, Segments:[]Segment{{"x",0}}},
		{Material:"m", Capacity:1, Segments:[]Segment{{"x",-1}}},
		{Material:"m", Capacity:1, Marks:[]int{-1}},
		{Material:"m", Capacity:1, Marks:[]int{2}},
		{Material:"m", Capacity:5, Gap:2, Segments:[]Segment{{"x",2},{"y",2}}},
	}
	for i, tc := range cases { if _, err := EncodeLayout(tc); err == nil { t.Errorf("case %d accepted: %+v", i, tc) } }
}

func TestEncodeLayoutGapOnlyBetweenSegments(t *testing.T) {
	got, err := EncodeLayout(Layout{Material:"m", Capacity:3, Gap:99, Segments:[]Segment{{"x",3}}})
	if err != nil { t.Fatal(err) }
	if got != "LAYOUT/1\n[base]\nmaterial=m\ncapacity=3\n[segments]\nx:3\n[marks]\n[totals]\nused=3\nremaining=0\n" { t.Fatalf("unexpected encoding %q", got) }
}

package solution

import "testing"

func TestReviewLayoutOverflow0326(t *testing.T) {
	maximum := int(^uint(0) >> 1)
	_, err := EncodeLayout(Layout{Material: "m", Capacity: maximum, Segments: []Segment{{Code: "a", Span: maximum}, {Code: "b", Span: 1}}})
	if err == nil { t.Fatal("accepted total span MaxInt+1 exceeding capacity MaxInt") }
}

