type Segment struct { Code string; Span int }
type Layout struct {
	Material string
	Capacity, Gap int
	Segments []Segment
	Marks []int
}

func EncodeLayout(x Layout) (string, error) {
	if x.Material == "" || x.Capacity < 0 || x.Gap < 0 { return "", errors.New("invalid layout") }
	used := 0
	for _, s := range x.Segments {
		if s.Code == "" || s.Span <= 0 { return "", errors.New("invalid segment") }
		used += s.Span + x.Gap
	}
	for _, m := range x.Marks {
		if m < 0 || m > x.Capacity { return "", errors.New("invalid mark") }
	}
	if used > x.Capacity { return "", errors.New("layout exceeds capacity") }
	var b strings.Builder
	fmt.Fprintf(&b, "LAYOUT/1\n[base]\nmaterial=%s\ncapacity=%d\n[segments]\n", x.Material, x.Capacity)
	for _, s := range x.Segments { fmt.Fprintf(&b, "%s:%d\n", s.Code, s.Span) }
	b.WriteString("[marks]\n")
	for _, m := range x.Marks { fmt.Fprintf(&b, "%d\n", m) }
	fmt.Fprintf(&b, "[totals]\nused=%d\nremaining=%d\n", used, x.Capacity-used)
	return b.String(), nil
}

